-- Staging only. All fixtures and lifecycle changes are rolled back.
begin;
set local plpgsql.check_asserts=on;
do $$
declare a uuid:=gen_random_uuid();u uuid:=gen_random_uuid();p uuid:=gen_random_uuid();p2 uuid:=gen_random_uuid();purchase_id uuid;oid uuid;req uuid:=gen_random_uuid();receipt_req uuid:=gen_random_uuid();complete_req uuid:=gen_random_uuid();bad_order uuid;result jsonb;v jsonb;payload jsonb;item jsonb;version timestamptz;changed_version timestamptz;before_count integer;balance integer;
begin
 insert into auth.users(id,aud,role,raw_user_meta_data,raw_app_meta_data) values(a,'authenticated','authenticated','{}','{}'),(u,'authenticated','authenticated','{"admin":true}','{}');
 insert into public.admin_profiles(user_id) values(a);
 insert into public.products(id,sku,name_zh,publication_status) values(p,'OPS-TEST-'||p,'操作驗收甲','published'),(p2,'OPS-TEST-'||p2,'操作驗收乙','published');
 perform set_config('request.jwt.claims','{}',true);execute 'set local role anon';
 begin perform public.admin_store_operation('create_purchase','{}',req);raise exception 'anon allowed';exception when insufficient_privilege then null;end;
 execute 'reset role';perform set_config('request.jwt.claims',jsonb_build_object('sub',u,'role','authenticated')::text,true);execute 'set local role authenticated';
 begin perform public.admin_store_operation('create_purchase','{}',req);raise exception 'nonadmin allowed';exception when insufficient_privilege then null;end;
 assert(select count(*) from public.orders)=0;
 begin perform 1 from private.store_operation_requests;raise exception 'request ledger leaked';exception when insufficient_privilege then null;end;
 execute 'reset role';perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true);execute 'set local role authenticated';
 payload:=jsonb_build_object('product_id',p,'purchased_at','2026-10-22','quantity',5,'unit_cost_twd','20.25','extra_cost_twd','0','supplier_name','Rollback fixture');
 result:=public.admin_store_operation('create_purchase',payload,req);purchase_id:=(result->>'id')::uuid;
 assert public.admin_store_operation('create_purchase',payload,req)=result,'purchase retry changed result';
 assert not exists(select 1 from public.inventory_balances where product_id=p),'purchase creation changed stock';
 begin perform public.admin_store_operation('create_purchase',payload||'{"quantity":6}',req);raise exception 'key payload reuse';exception when unique_violation then null;end;
 result:=public.admin_store_operation('receive_purchase',jsonb_build_object('id',purchase_id),receipt_req);
 assert (select quantity_on_hand from public.inventory_balances where product_id=p)=5;
 perform public.admin_store_operation('receive_purchase',jsonb_build_object('id',purchase_id),receipt_req);
 assert (select quantity_on_hand from public.inventory_balances where product_id=p)=5,'receipt retry doubled stock';
 begin perform public.admin_store_operation('receive_purchase',jsonb_build_object('id',purchase_id),gen_random_uuid());raise exception 'second receipt';exception when unique_violation then null;end;
 item:=jsonb_build_object('product_id',p,'quantity',2,'sale_unit_price_twd',100,'unit_cost_snapshot_twd','20.25');
 payload:=jsonb_build_object('channel','line','customer_alias','驗收客戶','customer_contact_private','PRIVATE CONTACT','customer_note','Rollback only','fee_twd',3,'other_cost_twd',2,'items',jsonb_build_array(item));
 req:=gen_random_uuid();result:=public.admin_store_operation('save_order',payload,req);oid:=(result->>'id')::uuid;
 assert public.admin_store_operation('save_order',payload,req)=result,'order retry duplicated';
 assert(select public_subtotal_twd from public.orders where id=oid)=200;
 assert(select quantity_on_hand from public.inventory_balances where product_id=p)=5;
 select updated_at into version from public.orders where id=oid;
 begin perform public.admin_store_operation('transition_order',jsonb_build_object('id',oid,'expected_updated_at',version,'status','completed','reason','不合法跳轉'),gen_random_uuid());raise exception 'invalid transition';exception when check_violation then null;end;
 begin perform public.admin_store_operation('save_order',payload||jsonb_build_object('id',oid,'expected_updated_at',version-interval '1 second'),gen_random_uuid());raise exception 'stale order edit';exception when sqlstate 'PT409' then null;end;
 before_count:=(select count(*) from public.order_items where order_id=oid);
 begin perform public.admin_store_operation('save_order',payload||jsonb_build_object('id',oid,'expected_updated_at',version,'items',jsonb_build_array(item,jsonb_build_object('product_id',p2,'quantity',-1))),gen_random_uuid());raise exception 'invalid item accepted';exception when check_violation then null;end;
 assert(select count(*) from public.order_items where order_id=oid)=before_count,'failed edit lost order items';
 v:=jsonb_build_object('id',oid,'expected_updated_at',version,'status','awaiting_payment','reason','價格確認完成');perform public.admin_store_operation('transition_order',v,gen_random_uuid());
 select updated_at into version from public.orders where id=oid;
 begin perform public.admin_store_operation('transition_order',jsonb_build_object('id',oid,'expected_updated_at',version,'status','paid_awaiting_purchase','reason','付款驗收測試','received_amount_twd',100,'received_at','2026-10-22T09:30:00+08:00','payment_reference_private','fixture'),gen_random_uuid());raise exception 'partial payment marked paid';exception when check_violation then null;end;
 v:=jsonb_build_object('id',oid,'expected_updated_at',version,'status','paid_awaiting_purchase','reason','實際收款確認','received_amount_twd',200,'received_at','2026-10-22T09:30:00+08:00','payment_reference_private','PAYMENT FIXTURE');
 req:=gen_random_uuid();perform public.admin_store_operation('transition_order',v,req);perform public.admin_store_operation('transition_order',v,req);
 assert(select received_amount_twd from public.orders where id=oid)=200;
 select updated_at into version from public.orders where id=oid;
 begin perform public.admin_store_operation('save_order',payload||jsonb_build_object('id',oid,'expected_updated_at',version),gen_random_uuid());raise exception 'paid order rewritten';exception when check_violation then null;end;
 perform public.admin_store_operation('transition_order',jsonb_build_object('id',oid,'expected_updated_at',version,'status','ordered_from_supplier','reason','已向供應訂購','supplier_reference_private','SUPPLIER FIXTURE'),gen_random_uuid());
 select updated_at into version from public.orders where id=oid;
 perform public.admin_store_operation('transition_order',jsonb_build_object('id',oid,'expected_updated_at',version,'status','arrived_for_check','reason','已實際到貨驗收'),gen_random_uuid());
 select updated_at into version from public.orders where id=oid;
 v:=jsonb_build_object('id',oid,'expected_updated_at',version);result:=public.admin_store_operation('complete_order',v,complete_req);assert public.admin_store_operation('complete_order',v,complete_req)=result;
 assert(select quantity_on_hand from public.inventory_balances where product_id=p)=3,'completion deducted wrong stock';
 update public.products set name_zh='已改名稱' where id=p;
 assert(select product_name_snapshot from public.order_items where order_id=oid limit 1)='操作驗收甲','product rename changed historical snapshot';
 select updated_at into version from public.orders where id=oid;
 perform public.admin_store_operation('transition_order',jsonb_build_object('id',oid,'expected_updated_at',version,'status','refund_pending','reason','客戶申請退款'),gen_random_uuid());
 select updated_at into version from public.orders where id=oid;
 begin perform public.admin_store_operation('transition_order',jsonb_build_object('id',oid,'expected_updated_at',version,'status','refunded','reason','退款測試確認','refund_amount_twd',201,'refund_recorded_at','2026-10-22T10:00:00+08:00','refund_reference_private','fixture'),gen_random_uuid());raise exception 'over-refund allowed';exception when check_violation then null;end;
 perform public.admin_store_operation('transition_order',jsonb_build_object('id',oid,'expected_updated_at',version,'status','refunded','reason','退款實際完成','refund_amount_twd',100,'refund_recorded_at','2026-10-22T10:00:00+08:00','refund_reference_private','REFUND FIXTURE'),gen_random_uuid());
 assert(select quantity_on_hand from public.inventory_balances where product_id=p)=3,'refund automatically restocked';
 v:=jsonb_build_object('id',oid,'product_id',p,'quantity',1,'reason','商品確實退回');req:=gen_random_uuid();perform public.admin_store_operation('return_stock',v,req);perform public.admin_store_operation('return_stock',v,req);
 assert(select quantity_on_hand from public.inventory_balances where product_id=p)=4;
 assert(select refund_amount_twd from public.orders where id=oid)=100,'physical return changed refund amount';
 assert(select sum(quantity_delta) from public.inventory_movements where product_id=p)=4;
 -- An unresolved price remains a draft; invalid multi-item completion rolls back every deduction.
 payload:=payload||jsonb_build_object('items',jsonb_build_array(item||'{"sale_unit_price_twd":null}'));
 result:=public.admin_store_operation('save_order',payload,gen_random_uuid());bad_order:=(result->>'id')::uuid;select updated_at into version from public.orders where id=bad_order;
 begin perform public.admin_store_operation('transition_order',jsonb_build_object('id',bad_order,'expected_updated_at',version,'status','awaiting_payment','reason','未確認價格測試'),gen_random_uuid());raise exception 'inquiry price confirmed';exception when check_violation then null;end;
 execute 'reset role';
 assert(select count(*) from private.store_operation_requests where actor_user_id=a)>0;
end; $$;
select 'passed' as operations_acceptance;
rollback;
